using UnityEngine;
using UnityEngine.InputSystem;
// Sleep-cap and pillow creature. No humanoid animation or wing motion is reused.
public sealed class NiaolongCompanion:MonoBehaviour
{
 public enum Gesture { Idle,HugPillow,SleepyNod,HappyBounce,StarWish,CuriousPeek,SoftTurn,Surprised,Comfort,OneHandHold,PillowToss }
 public Transform owner,body,hug,hat,pompom,leftHand,rightHand,leftFoot,rightFoot,leftEye,rightEye;
 public bool Equipped {get;private set;}public bool Moving {get;private set;}public float Visibility {get;private set;}public Gesture Action {get;private set;}public int ActionsStarted {get;private set;}public int MovementFrames {get;private set;}
 public static readonly Gesture[] Ambient={Gesture.HugPillow,Gesture.SleepyNod,Gesture.HappyBounce,Gesture.StarWish,Gesture.CuriousPeek,Gesture.SoftTurn,Gesture.OneHandHold,Gesture.PillowToss};
 public float ActionTime=>actionTime;public float Blend=>Ease(actionTime/.8f)*Ease((Duration(Action)-actionTime)/.9f);
 public bool preview;float time,actionTime,wait=.9f,flight,speed,blinkAt=2,blinkTime=10,spin,orbit=-1,alertAt,lastHurt=-10;int last=-1;Vector3 previous,velocity;Quaternion facing;Health health;
 Vector3 pomRest,hugRest;Quaternion hatRest;
 void Awake(){CaptureRest();}
 public void CaptureRest(){pomRest=pompom.localPosition;hugRest=hug.localPosition;hatRest=hat.localRotation;facing=transform.rotation;}
 public void Bind(Transform target){owner=target;previous=target.position;transform.position=target.position+target.right*.7f+Vector3.up*1.25f;health=target.GetComponent<Health>();if(health)health.Damaged+=Hurt;}
 void OnDestroy(){if(health)health.Damaged-=Hurt;}
 void Hurt(Health h,DamageInfo info){if(Equipped&&Time.unscaledTime-lastHurt>6){lastHurt=Time.unscaledTime;Play(Gesture.Comfort);}}
 public static float Duration(Gesture a)=>a==Gesture.PillowToss?6:a==Gesture.SleepyNod?6:a==Gesture.SoftTurn?6:4.8f;
 static float Ease(float p){p=Mathf.Clamp01(p);return p*p*p*(p*(p*6-15)+10);}
 public void SetEquipped(bool value){Equipped=value;if(value&&owner){previous=owner.position;transform.position=owner.position+owner.right*.72f+Vector3.up*1.25f;velocity=Vector3.zero;Action=Gesture.Idle;actionTime=0;wait=.8f;}}
 public void Play(Gesture value){Action=value;actionTime=0;ActionsStarted++;}
 public void Circle(){if(Equipped)orbit=0;}
 void Update(){if(preview||!owner||!owner.gameObject.activeInHierarchy||Time.timeScale<=0||!Equipped||Visibility<.95f||CompanionWardrobe.IsBagOpen)return;if(Mouse.current!=null&&Mouse.current.leftButton.wasPressedThisFrame&&Camera.main){var ray=Camera.main.ScreenPointToRay(Mouse.current.position.ReadValue());foreach(var r in GetComponentsInChildren<Renderer>())if(r.bounds.IntersectRay(ray)){Circle();break;}}}
 void LateUpdate(){if(preview)return;if(!owner){Destroy(gameObject);return;}if(!owner.gameObject.activeInHierarchy){body.gameObject.SetActive(false);return;}float dt=Time.deltaTime;if(dt<=0)return;time+=dt;Visibility=Mathf.MoveTowards(Visibility,Equipped?1:0,dt*3);body.gameObject.SetActive(Visibility>.001f);Vector3 v=Vector3.ProjectOnPlane(owner.position-previous,Vector3.up)/Mathf.Max(dt,.001f);previous=owner.position;speed=Mathf.Lerp(speed,v.magnitude>25?0:v.magnitude,1-Mathf.Exp(-dt*7));Moving=speed>.2f;if(Visibility<=0)return;
 if(Action!=Gesture.Idle){actionTime+=dt;if(actionTime>=Duration(Action)){Action=Gesture.Idle;actionTime=0;wait=Random.Range(.9f,1.6f);}}else if(Equipped&&!CompanionWardrobe.IsBagOpen){wait-=dt;if(wait<=0){int next=Random.Range(0,Ambient.Length-1);if(next>=last)next++;last=next%Ambient.Length;Play(Ambient[last]);}}
 if(Equipped&&time>alertAt){alertAt=time+1;foreach(var enemy in FindObjectsByType<MountedKnightBrain>(FindObjectsSortMode.None))if(enemy.enabled&&Vector3.Distance(owner.position,enemy.transform.position)<enemy.attackRange&&Action!=Gesture.Comfort){Play(Gesture.Surprised);alertAt=time+10;break;}}
 float p=actionTime/Duration(Action),e=Blend;Vector3 offset=new Vector3(.73f,1.25f,-.12f);if(Action==Gesture.HappyBounce)offset.y+=.19f*Mathf.Pow(Mathf.Sin(p*Mathf.PI*3),2)*e;if(Action==Gesture.StarWish)offset+=new Vector3(.16f*Mathf.Sin(p*6.283f),.18f*Mathf.Sin(p*Mathf.PI),.12f*Mathf.Sin(p*6.283f))*e;if(Action==Gesture.CuriousPeek)offset+=new Vector3(-.14f,.05f,.32f)*Mathf.Sin(p*Mathf.PI)*e;if(Action==Gesture.SleepyNod)offset.y-=.12f*e;
 if(orbit>=0){orbit+=dt;float q=Mathf.Clamp01(orbit/5.5f),a=Mathf.PI*Mathf.Sin(q*Mathf.PI);offset=new Vector3(.76f*Mathf.Cos(a),1.3f+.1f*Mathf.Sin(q*6.283f),.76f*Mathf.Sin(a));if(q>=1)orbit=-1;}
 Vector3 goal=owner.position+owner.right*offset.x+Vector3.up*offset.y+owner.forward*offset.z;if(Vector3.Distance(goal,transform.position)>8){transform.position=goal;velocity=Vector3.zero;}transform.position=Vector3.SmoothDamp(transform.position,goal,ref velocity,.22f);Vector3 d=Moving?Vector3.Lerp(owner.forward,v.normalized,.5f):owner.forward;if(Action==Gesture.CuriousPeek)d=Vector3.Lerp(d,Vector3.ProjectOnPlane(owner.position-transform.position,Vector3.up).normalized,e*.6f);if(d.sqrMagnitude>.01f)facing=Quaternion.Slerp(facing,Quaternion.LookRotation(d),1-Mathf.Exp(-dt*5));transform.rotation=facing;Pose(time,dt,Moving);}
 public void Sample(Gesture gesture,float seconds){preview=true;Action=gesture;actionTime=seconds;Visibility=1;Pose(seconds,1,false);}
 public void Pose(float clock,float dt,bool moving){flight=Mathf.Lerp(flight,moving?1:0,1-Mathf.Exp(-dt*5));if(moving)MovementFrames++;float e=Blend,p=actionTime/Duration(Action);float lean=flight*12,roll=Mathf.Sin(clock*1.8f)*2,squash=.012f*Mathf.Sin(clock*2.2f),hugAmount=0,close=0,turn=0;
 switch(Action){case Gesture.HugPillow:hugAmount=.023f*e;lean+=8*e;roll+=6*Mathf.Sin(p*6.283f)*e;break;case Gesture.SleepyNod:lean+=13*e*(.7f+.3f*Mathf.Sin(p*Mathf.PI*3));roll+=8*e;close=e;squash-=.035f*e;hugAmount=.018f*e;break;case Gesture.HappyBounce:squash+=.065f*Mathf.Sin(p*Mathf.PI*6)*e;roll+=8*Mathf.Sin(p*Mathf.PI*6)*e;hugAmount=.02f*e;break;case Gesture.StarWish:lean-=8*e;hugAmount=-.025f*e;roll+=5*Mathf.Sin(p*6.283f)*e;break;case Gesture.CuriousPeek:roll-=17*Mathf.Sin(p*Mathf.PI)*e;break;case Gesture.SoftTurn:turn=360*Ease((p-.13f)/.74f);roll+=7*Mathf.Sin(p*6.283f)*e;break;case Gesture.Surprised:lean-=12*e;squash+=.06f*e;hugAmount=.025f*e;break;case Gesture.Comfort:lean+=9*e;roll-=8*e;hugAmount=.03f*e;break;}
 spin=Mathf.LerpAngle(spin,turn,1-Mathf.Exp(-dt*8));body.localRotation=Quaternion.Euler(lean,spin,roll);body.localPosition=Vector3.up*(.025f*Mathf.Sin(clock*2.5f));body.localScale=new Vector3(1-squash*.5f,1+squash,1-squash*.5f)*Ease(Visibility);
 hug.localPosition=Vector3.Lerp(hug.localPosition,hugRest+new Vector3(0,hugAmount*.6f,-hugAmount),1-Mathf.Exp(-dt*7));hug.localRotation=Quaternion.Euler(-4*e,0,2*Mathf.Sin(clock*2));float compression=1-hugAmount*1.7f;var pillow=hug.Find("Soft four-corner pillow");if(pillow)pillow.localScale=new Vector3(1+Mathf.Abs(hugAmount)*.7f,1+Mathf.Abs(hugAmount)*.5f,compression);
 leftHand.localRotation=Quaternion.Euler(0,0,6*e);rightHand.localRotation=Quaternion.Euler(0,0,-6*e);leftFoot.localRotation=Quaternion.Euler(flight*27+Mathf.Sin(clock*3)*4,0,0);rightFoot.localRotation=Quaternion.Euler(flight*25-Mathf.Sin(clock*3)*4,0,0);
 hat.localRotation=Quaternion.Slerp(hat.localRotation,hatRest*Quaternion.Euler(-lean*.25f+Mathf.Sin(clock*2.5f-.7f)*2,0,-roll*.35f),1-Mathf.Exp(-dt*6));pompom.localPosition=Vector3.Lerp(pompom.localPosition,pomRest+new Vector3(.009f*Mathf.Sin(clock*3-.9f),.013f*Mathf.Sin(clock*3-1.2f),.005f*Mathf.Sin(clock*2)),1-Mathf.Exp(-dt*7));
 if(clock>blinkAt){blinkAt=clock+Random.Range(2.4f,4.5f);blinkTime=clock;}float blink=1-Mathf.Sin(Mathf.Clamp01((clock-blinkTime)/.2f)*Mathf.PI);blink=Mathf.Lerp(blink,.10f,close);leftEye.localScale=rightEye.localScale=new Vector3(1,Mathf.Max(.07f,blink),1);leftEye.GetComponent<NiaolongSurfaceEye>()?.UpdateGeometry();rightEye.GetComponent<NiaolongSurfaceEye>()?.UpdateGeometry();var softRig=GetComponent<NiaolongSoftRig>();if(softRig)softRig.Apply(clock,e,p);}
}
